def countWithinLimit(nums, limit):
    from collections import deque
    mx = deque()
    mn = deque()
    left = 0
    total = 0
    for i, x in enumerate(nums):
        while mx and nums[mx[-1]] <= x:
            mx.pop()
        mx.append(i)
        while mn and nums[mn[-1]] >= x:
            mn.pop()
        mn.append(i)
        while nums[mx[0]] - nums[mn[0]] > limit:
            left += 1
            if mx[0] < left:
                mx.popleft()
            if mn[0] < left:
                mn.popleft()
        total += i - left + 1
    return total
